-- ============================================================
-- Quiz coverage for devops/jenkins and devops/argocd (batch 3).
--
-- Both technologies' registry entries stay ALIASED to
-- infrastructure/jenkins/* and infrastructure/argocd/* for every
-- tab except troubleshooting (see lib/content/index.ts) --
-- unlike git in batch 2, infrastructure/jenkins and
-- infrastructure/argocd turned out to be correctly-topical,
-- comprehensive, and good-quality content (the same outcome as
-- nginx in batch 2), so they were kept live rather than
-- unshadowed. Questions below are grounded in that actually-live
-- infrastructure/ content (overview, fundamentals, intermediate,
-- advanced -- the four tabs with real, substantive material),
-- not the devops/ copies sitting unused on disk.
-- ============================================================

INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES

-- ---------- devops/jenkins/overview ----------
('devops', 'jenkins', 'overview', 'Why should the Jenkins controller (master) never run build jobs directly?', '["The controller physically cannot execute shell steps", "A hung, memory-heavy, or malicious build running on the controller can degrade or take down the entire Jenkins instance, not just that one job", "Running builds on the controller is against Jenkins'' license terms", "Agents are always faster than the controller at running builds"]', 1, 'Agent isolation exists specifically to contain the blast radius of a bad build -- a build that crashes an agent does not threaten the controller''s own stability, which affects every other job on the instance.', 'beginner'),
('devops', 'jenkins', 'overview', 'What is the actual difference between Declarative and Scripted Pipeline syntax?', '["They compile to different binary formats", "Declarative uses a structured, opinionated pipeline {} block that is easier to validate and read; Scripted is full Groovy code, more flexible but harder to maintain", "Scripted Pipeline is deprecated and no longer supported", "Declarative Pipeline cannot use environment variables"]', 1, 'Best practice is to default to Declarative and drop into a script {} block (or full Scripted) only for logic that genuinely needs Groovy''s flexibility, since Declarative provides better validation and error messages.', 'beginner'),
('devops', 'jenkins', 'overview', 'Where should secrets (API keys, registry passwords) actually be referenced from in a Jenkinsfile?', '["Hardcoded directly as string literals so builds are reproducible", "Jenkins'' Credentials Store (or an external secrets manager), referenced by ID via withCredentials() or credentials() -- never as literal values in the file", "Environment variables set on the developer''s own laptop", "A .env file committed alongside the Jenkinsfile"]', 1, 'The Jenkinsfile is committed to Git and often widely readable -- credentials() and withCredentials() inject the actual secret value at runtime from Jenkins'' own store, keeping the pipeline definition itself safe to have in source control.', 'beginner'),
('devops', 'jenkins', 'overview', 'A pipeline stage that used to take 10 minutes now takes 40. What is the correct first diagnostic step?', '["Immediately add more parallel stages without investigating", "Check the Stage View or Blue Ocean timeline for real per-stage timing data before guessing at a cause", "Restart the Jenkins controller", "Assume it is always a caching problem and add a cache block"]', 1, 'Guessing at a cause (agent overhead, missing caching, a slow new stage) without first looking at actual per-stage timing risks fixing the wrong thing -- the Stage View shows exactly where time is actually going.', 'intermediate'),
('devops', 'jenkins', 'overview', 'What does the post { failure {} } block in a Declarative Pipeline guarantee that code inside a specific stage cannot?', '["Nothing -- post and stage-level code behave identically", "It runs regardless of which stage the pipeline reached or failed at, making it the correct place for cleanup and failure notifications", "It only runs if every single stage succeeds first", "post blocks can only send Slack messages, not run shell commands"]', 1, 'Code placed inside one specific stage is skipped entirely if an earlier stage fails first; post conditions (always, success, failure, unstable) are guaranteed to run regardless of where in the pipeline execution actually stopped.', 'beginner'),

-- ---------- devops/jenkins/fundamentals ----------
('devops', 'jenkins', 'fundamentals', 'In a Jenkinsfile, what does DOCKER_CREDS = credentials(''docker-hub-creds'') actually do for a usernamePassword credential?', '["Prints the credential value to the build log for debugging", "Automatically creates DOCKER_CREDS_USR and DOCKER_CREDS_PSW environment variables bound to the stored username and password", "Deletes the credential from Jenkins'' store after first use", "Only works for SSH key credentials, not username/password"]', 1, 'This binding pattern is why credentials() is preferred over manually parsing a secret string -- Jenkins creates the _USR/_PSW variables automatically and masks their values in console output.', 'beginner'),
('devops', 'jenkins', 'fundamentals', 'Why does the Jenkins Kubernetes plugin provision a fresh pod for each build rather than reusing a static agent?', '["Kubernetes pods start instantly with zero overhead, always", "It gives no idle cost when nothing is building, a clean environment on every single build with no state leaking between builds, and per-job container images -- at the real cost of per-build pod startup latency (commonly 10-30 seconds)", "Static agents are no longer supported by Jenkins at all", "Pods are required because Jenkins cannot run on virtual machines"]', 1, 'This is a genuine tradeoff, not a strictly-better choice -- ephemeral pods trade some startup latency for elasticity, cost efficiency when idle, and build-to-build isolation that a shared static agent does not have.', 'intermediate'),
('devops', 'jenkins', 'fundamentals', 'What is the actual risk of referencing a Shared Library with @Library(''my-lib'') _ (no version pinned) instead of @Library(''my-lib@v2.1.0'') _?', '["Unpinned libraries run noticeably slower", "Every pipeline using the unpinned reference can silently change behavior the moment someone pushes to the library''s default branch -- a surprising, hard-to-trace change in a shared build dependency", "Jenkins refuses to load an unpinned Shared Library at all", "Unpinned libraries cannot define reusable functions in vars/"]', 1, 'Pinning to a tagged version means a library change only affects consumers when they deliberately bump their reference -- an unpinned/floating reference applies to every consuming pipeline on its very next run, with no warning.', 'intermediate'),
('devops', 'jenkins', 'fundamentals', 'Why is a minimal, deliberately-chosen Jenkins plugin set considered a real operational advantage, not just tidiness?', '["Jenkins charges a licensing fee per installed plugin", "Every installed plugin is a dependency that can break on a Jenkins core upgrade or introduce its own security vulnerabilities needing separate patching", "Plugins are only cosmetic and never affect pipeline behavior", "Jenkins has a hard limit of 10 installed plugins"]', 1, 'Plugin sprawl -- installing everything that looks potentially useful -- is a common, genuine source of fragile, hard-to-upgrade Jenkins instances in real production use, not a theoretical concern.', 'intermediate'),
('devops', 'jenkins', 'fundamentals', 'What is the practical reason to always store the Jenkinsfile in source control alongside the code it builds ("Pipeline as Code")?', '["Jenkins refuses to run pipelines defined outside of source control", "It gets pipeline changes reviewed via the same pull-request process as application code, and the pipeline definition for any given commit is exactly reproducible", "It makes the Jenkinsfile run faster than a UI-configured job", "Source-controlled Jenkinsfiles do not require a Jenkinsfile filename"]', 1, 'A UI-configured job lives disconnected from the code''s own history -- Pipeline as Code means the exact pipeline that ran for a given commit is always knowable and reviewable, the same as any other code change.', 'beginner'),

-- ---------- devops/jenkins/intermediate ----------
('devops', 'jenkins', 'intermediate', 'In a Multibranch Pipeline, what determines whether a job gets created for a given branch or pull request?', '["Every branch in the repository always gets a job, with no exceptions", "Jenkins scans the repository and creates one job per branch/PR that contains a Jenkinsfile at the configured path", "Only the main branch ever gets a job", "Branch jobs must be manually created one at a time in the Jenkins UI"]', 1, 'This auto-discovery is what enables PR builds and branch isolation -- Jenkins automatically creates and deletes branch jobs as branches appear and disappear in the repository, based on Jenkinsfile presence.', 'intermediate'),
('devops', 'jenkins', 'intermediate', 'In a declarative pipeline stage, what does when { branch ''main'' } actually control?', '["Which Jenkins agent the stage runs on", "Whether that specific stage executes at all, based on the condition -- skipping it entirely on non-matching branches", "The Groovy version used to parse that stage", "Whether the stage''s output gets archived as a build artifact"]', 1, 'when conditions (branch, environment, expression, changeset, and others) gate stage execution -- a common pattern is running tests on every branch but restricting deploy stages to when { branch ''main'' }.', 'beginner'),
('devops', 'jenkins', 'intermediate', 'Why does build job: ''deploy-pipeline'', wait: true, propagate: true matter for a CI pipeline that triggers a separate deploy pipeline?', '["wait and propagate have no effect on pipeline behavior", "wait: true blocks until the triggered job finishes, and propagate: true fails the calling pipeline if the triggered deploy pipeline fails -- without both, a failed downstream deploy could go unnoticed", "These parameters only work for Freestyle jobs, never Pipeline jobs", "wait: true is required for the build step to compile at all"]', 1, 'Without propagate: true, the calling pipeline could report success even though the job it triggered actually failed -- a real, easy-to-miss gap in end-to-end pipeline reliability.', 'intermediate'),
('devops', 'jenkins', 'intermediate', 'What is the actual purpose of a Jenkins Job DSL seed job (a groovy script that programmatically defines pipelineJob(...) for several services)?', '["It replaces the need for a Jenkinsfile in each service''s repository entirely", "It generates Jenkins job definitions programmatically from one script -- useful when the same job shape (pipeline + polling trigger + deploy job) needs to be created consistently across many services", "It is only usable for Freestyle jobs, never Pipeline jobs", "Job DSL scripts run inside the Groovy sandbox by default with no special permission needed"]', 1, 'Instead of manually clicking through the Jenkins UI to create a near-identical job per service, a Job DSL seed script defines them all from one script.each { } loop -- consistent, and easy to extend when a new service is added.', 'advanced'),
('devops', 'jenkins', 'intermediate', 'What real risk does a permission string like authorizationMatrix { permission(''hudson.model.Item.Build:ops-team'') } address, and why does getting the permission ID exactly right matter?', '["It has no real effect -- authorizationMatrix blocks are cosmetic", "It grants the ops-team group specifically the Build permission on that job -- an incorrect or malformed permission ID silently fails to grant the intended access rather than raising a clear error", "It only restricts access to the Jenkins CLI, not the web UI", "Permission strings are validated at Jenkinsfile parse time and always fail loudly if wrong"]', 1, 'Fine-grained authorization matrix permissions are how a Job DSL script or CasC config restricts who can build/read/configure a specific job -- getting the exact permission ID right is what actually makes the restriction take effect as intended.', 'advanced'),

-- ---------- devops/jenkins/advanced ----------
('devops', 'jenkins', 'advanced', 'In a Jenkins Declarative Matrix build (matrix { axes { ... } }), what does the excludes block accomplish?', '["It deletes the entire matrix stage from the pipeline", "It removes specific axis-value combinations from the generated build matrix -- e.g. skipping a Windows + Python 3.10 combination that is not actually supported", "It excludes the matrix stage from post block notifications only", "excludes only works when there is a single axis defined"]', 1, 'Without excludes, a matrix with 3 platforms x 3 Python versions runs all 9 combinations -- excludes lets you drop specific combinations that genuinely do not need testing (or do not work), without hand-writing 8 separate stages instead.', 'advanced'),
('devops', 'jenkins', 'advanced', 'What is the practical difference between the post conditions regression and fixed in a Declarative Pipeline?', '["They are aliases for the same condition", "regression fires when the previous build succeeded but this one failed; fixed fires when the previous build failed but this one succeeded -- both compare against the immediately preceding build, not just the current result", "regression only applies to security scan stages", "fixed can only be used inside a stage block, never inside post at pipeline level"]', 1, 'Both are genuinely useful for noise reduction in notifications -- alerting specifically on regression (something that just broke) or fixed (something that just got better) is more actionable than alerting on every failure or every success regardless of the previous build''s outcome.', 'advanced'),
('devops', 'jenkins', 'advanced', 'In Jenkins Configuration as Code (JCasC), what problem does defining the Jenkins instance''s own configuration as versioned YAML actually solve?', '["It makes pipelines run faster by precompiling Groovy", "Reproducing an exact Jenkins configuration after a disaster (or replicating it for a second team) becomes reviewable and versioned instead of relying on someone remembering exactly what was clicked through the UI", "JCasC is required before any Jenkinsfile can be written", "It replaces the need for the Credentials plugin entirely"]', 1, 'CasC does for the Jenkins instance itself (security realm, authorization, plugin config) what Pipeline as Code does for individual jobs -- versioned, reviewable, and reproducible rather than living only in UI state.', 'intermediate'),
('devops', 'jenkins', 'advanced', 'Why does a Blue-Green deployment pipeline stage typically query the live service selector (kubectl get svc ... -o jsonpath) before deciding which color to deploy to?', '["To generate a random color for load-testing purposes", "To determine which color (blue or green) is currently NOT receiving production traffic, so the new version deploys to the inactive one without disrupting live traffic", "Kubernetes services require a color label to function at all", "jsonpath queries are required before any kubectl apply command"]', 1, 'Deploying to the currently-inactive color, smoke-testing it directly, and only then switching the service selector is what makes Blue-Green deployment a genuinely zero-downtime pattern -- deploying blind to a color without checking which is active risks overwriting the live version.', 'advanced'),
('devops', 'jenkins', 'advanced', 'What is the real tradeoff of reusing the same Kubernetes agent pod across all pipeline stages (a single pod with multiple named containers) instead of provisioning a new pod per stage?', '["There is no tradeoff -- reusing the pod is strictly better in every case", "It avoids repeated pod startup latency for every stage, at the cost of all stages sharing the same pod''s resource limits and lifecycle -- a crashed container in one stage can affect the whole pod", "Reusing pods is required by the Kubernetes plugin and cannot be disabled", "It only works if every stage uses the exact same container image"]', 1, 'Faster overall pipeline time (one pod startup instead of several) is a real, genuine benefit, but it does mean stages are no longer as isolated from each other as fully separate pods would be -- a real tradeoff, not a free win.', 'advanced'),

-- ---------- devops/argocd/overview ----------
('devops', 'argocd', 'overview', 'What is the core architectural difference between a traditional CI-push deployment model and ArgoCD''s GitOps pull model?', '["They are functionally identical, just different terminology", "In the push model, the CI pipeline holds cluster credentials and applies changes directly; in ArgoCD''s pull model, ArgoCD runs inside the cluster and pulls from Git, so no external CI system needs direct cluster access", "GitOps means Git hosts the actual running containers instead of a registry", "Push and pull only differ in which protocol (HTTP vs SSH) is used to reach the cluster"]', 1, 'This inversion is the actual security and auditability benefit of GitOps -- it is not just a stylistic preference, it removes a real, standing credential exposure from the CI system.', 'beginner'),
('devops', 'argocd', 'overview', 'An Application shows Synced but Degraded. What does this combination actually mean?', '["ArgoCD failed to apply the manifests and needs a manual retry", "ArgoCD applied the manifests exactly as written (cluster matches Git), but the resulting Kubernetes resources are not healthy -- e.g. pods are crash-looping", "Synced and Degraded cannot occur at the same time -- this is a UI display bug", "Degraded means the Application was deleted from Git but still exists in the cluster"]', 1, 'Sync status and Health status are two separate axes -- Synced only confirms the apply succeeded, not that the deployed workload is actually working correctly.', 'intermediate'),
('devops', 'argocd', 'overview', 'What does selfHeal: true actually do when someone runs kubectl edit directly against a resource ArgoCD manages?', '["Nothing -- selfHeal only affects new resources, never existing ones", "ArgoCD detects the drift and reverts the manual change back to match Git on its next reconciliation, overwriting the manual edit", "It sends a Slack notification but takes no automated action", "It permanently locks the resource so kubectl edit is rejected by the API server"]', 1, 'This is GitOps enforcement in practice -- with selfHeal enabled, Git really is the source of truth, not just true until someone manually intervenes; some teams deliberately disable it in production to avoid reverting emergency fixes before they land in Git too.', 'beginner'),
('devops', 'argocd', 'overview', 'What is the correct GitOps-preferred way to roll back a bad production deployment managed by ArgoCD?', '["Always use argocd app rollback, since it is faster than any Git operation", "git revert the offending commit and push -- ArgoCD auto-syncs the cluster back to the previous state, keeping Git history accurate as the actual record of what is running", "Manually edit the live Deployment with kubectl and hope selfHeal does not revert it", "Delete the Application and recreate it from scratch"]', 1, 'argocd app rollback reverts only the live cluster state without touching Git, leaving Git and the cluster inconsistent until someone follows up -- git revert keeps the two in sync and preserves an accurate history.', 'intermediate'),
('devops', 'argocd', 'overview', 'What is the actual purpose of an AppProject that a single default project does not provide?', '["AppProjects are purely cosmetic groupings with no access-control effect", "An AppProject restricts which Git repos, cluster/namespace destinations, and Kubernetes resource kinds a group of Applications can use -- the mechanism that lets one shared ArgoCD instance safely serve multiple teams", "AppProjects are required only when using Helm charts, not plain YAML", "Every Application requires its own dedicated AppProject -- they cannot be shared across Applications"]', 1, 'Without an AppProject, every Application implicitly belongs to the unrestricted default project -- AppProject scoping is what confines a team''s Applications to only their own repos and namespaces.', 'intermediate'),

-- ---------- devops/argocd/fundamentals ----------
('devops', 'argocd', 'fundamentals', 'In an ArgoCD Application spec, what specifically does syncPolicy.automated.prune: true control?', '["Whether ArgoCD compresses manifests before applying them", "Whether resources that have been REMOVED from the Git-tracked manifests get deleted from the cluster on the next sync -- without it, ArgoCD only adds/updates, never removes", "Whether ArgoCD prunes old Git commit history", "Whether failed syncs are automatically retried"]', 1, 'This is a common point of confusion -- deleting a resource from a Helm values file or manifest directory does NOT delete it from the cluster unless prune is explicitly enabled.', 'beginner'),
('devops', 'argocd', 'fundamentals', 'What problem does the App of Apps pattern (a parent Application watching a directory of other Application manifests) actually solve?', '["It reduces the number of Kubernetes namespaces required", "Manually creating and syncing 15+ Application objects individually does not scale -- a parent Application lets adding a new service be as simple as adding one YAML file to a watched directory", "It is required before ArgoCD can manage more than one cluster", "It replaces the need for an AppProject entirely"]', 1, 'Bootstrapping an entire environment becomes syncing one parent Application, which then creates and manages all the child Applications defined in the watched Git directory.', 'intermediate'),
('devops', 'argocd', 'fundamentals', 'In ArgoCD sync hooks, what is the practical difference between a PreSync and a PostSync hook?', '["They run in a random order determined by Kubernetes scheduling", "PreSync hooks (e.g. a database migration Job) run BEFORE the main sync applies the rest of the manifests; PostSync hooks (e.g. a smoke test) run AFTER", "PostSync hooks run before PreSync hooks despite the naming", "Hooks only work for ConfigMap and Secret resources, not Jobs"]', 1, 'This ordering is what makes hooks useful for real deployment sequencing -- running database migrations before the application that depends on the new schema, then verifying with a smoke test only after the application itself is deployed.', 'intermediate'),
('devops', 'argocd', 'fundamentals', 'Why does an AppProject''s syncWindows deny rule (e.g. denying Friday 6pm through Monday 6am) matter operationally?', '["It has no functional effect -- syncWindows is purely documentation", "It blocks ArgoCD from syncing the specified applications during that window, preventing production deployments outside of times when someone can actively respond to a problem", "It only restricts manual argocd app sync commands, not automated syncs", "syncWindows can only allow syncs, never deny them"]', 1, 'A deny sync window is a real operational safeguard -- even if a change merges to main over a weekend, ArgoCD will not apply it to production until the window opens and someone is actually available to monitor the result.', 'advanced'),
('devops', 'argocd', 'fundamentals', 'What does the ApplicationSet Cluster Generator actually generate Applications from?', '["A static list hardcoded directly in the ApplicationSet manifest", "One Application per cluster that ArgoCD has registered and that matches the generator''s label selector -- deploying the same Application definition to every matching cluster automatically", "A list of Git branches instead of clusters", "It only works with a single, hardcoded cluster and cannot use selectors"]', 1, 'This is essential for platform teams managing infrastructure across many clusters -- registering a new cluster with a matching label is enough for it to automatically receive the ApplicationSet''s Applications, no manual Application creation needed.', 'advanced'),

-- ---------- devops/argocd/intermediate ----------
('devops', 'argocd', 'intermediate', 'What is the actual difference between an ApplicationSet List generator and a Git directory generator?', '["They produce identical output in every case", "List generator uses an explicit, hand-maintained list of elements (fixed known environments); Git directory generator automatically creates one Application per matching directory found in a Git repo", "Git directory generators cannot use template variables, only List generators can", "List generators only work with Helm charts"]', 1, 'List is appropriate for a small, fixed, rarely-changing set of environments; Git directory generator scales automatically as services are added -- a new directory in the repo produces a new Application with no ApplicationSet edit required.', 'intermediate'),
('devops', 'argocd', 'intermediate', 'In an AppProject''s RBAC policy, what does p, proj:team-backend:developer, applications, sync, team-backend/*, allow actually grant?', '["Full admin access to every Application in the ArgoCD instance", "The developer role within the team-backend project is allowed to trigger sync specifically on Applications whose name matches the team-backend/* pattern", "Read-only access with no ability to trigger a sync", "Access to delete Applications, since sync implies delete permission"]', 1, 'This is a Casbin-style policy scoped to one specific action (sync) on one specific project''s Applications -- it deliberately does not grant delete or create, which would need their own separate policy lines.', 'advanced'),
('devops', 'argocd', 'intermediate', 'What is the actual function of the ArgoCD Image Updater''s write-back-method: git annotation?', '["It tells the Image Updater to only log detected image updates without applying them", "It configures the Image Updater to commit the new image tag back to the Git repository (rather than only updating the live cluster object directly), keeping Git accurate as the record of what is deployed", "It disables Git-based sync entirely for that Application", "It is required only when using plain YAML manifests, never Helm"]', 1, 'Without write-back-method: git, an automatic image update could change what is running in the cluster without that change ever being reflected in Git -- breaking the GitOps guarantee that Git accurately describes the deployed state.', 'advanced'),
('devops', 'argocd', 'intermediate', 'Why might an ArgoCD Application show OutOfSync on a Deployment''s replicas field even though nobody manually changed it?', '["ArgoCD always shows every field as OutOfSync by design", "An HPA (Horizontal Pod Autoscaler) actively manages replicas outside of Git -- without an ignoreDifferences entry for that field, ArgoCD sees the live value differing from Git''s and flags it as drift", "OutOfSync on replicas means the Deployment failed to start any pods", "This can only happen if selfHeal is enabled"]', 1, 'This is exactly why ignoreDifferences with a jsonPointer targeting /spec/replicas exists -- it tells ArgoCD to not treat HPA-managed field changes as drift requiring correction, since that field is legitimately meant to be controlled by something other than Git.', 'intermediate'),
('devops', 'argocd', 'intermediate', 'What problem do ArgoCD Notifications triggers like on-sync-failed and on-health-degraded solve that the ArgoCD UI alone does not?', '["The ArgoCD UI cannot display sync status at all without Notifications installed", "The UI shows current state on demand, but Notifications proactively pushes alerts (Slack, email, PagerDuty) when a specific event happens, so a team finds out about a failure without someone having to be actively watching the UI", "Notifications are required before automated sync can be enabled", "Triggers only work for Applications using the App of Apps pattern"]', 1, 'Subscribing specifically to failure and degradation events (rather than every successful sync) keeps the notification channel meaningful -- routing every successful sync to Slack too quickly becomes noise nobody actually reads.', 'intermediate'),

-- ---------- devops/argocd/advanced ----------
('devops', 'argocd', 'advanced', 'In a hub-and-spoke ArgoCD setup managing multiple external clusters, what does argocd cluster add actually do?', '["It creates a brand new Kubernetes cluster from scratch", "It registers an external cluster''s API server (using the current kubeconfig context) with the hub ArgoCD instance, so Applications can target it as a destination", "It copies the hub cluster''s entire ArgoCD installation into the spoke cluster", "It is only needed for clusters in the same cloud region as the hub"]', 1, 'Once registered, an Application''s destination.server can point at the spoke cluster''s API server URL just like any other destination -- one ArgoCD control plane managing several clusters without installing ArgoCD in each one.', 'advanced'),
('devops', 'argocd', 'advanced', 'Why does ArgoCD Disaster Recovery planning need to specifically back up Application and AppProject objects, when the actual deployed workload manifests all live safely in Git already?', '["Kubernetes automatically backs up all objects in every namespace by default", "The mapping of which Git repo/path goes to which cluster/namespace, plus repo credentials and RBAC config, lives only in ArgoCD''s own state and is not reconstructable from the target clusters'' Git repos alone", "Git repos are considered unreliable and need a secondary backup regardless", "Application and AppProject objects contain the actual container images, which would otherwise be lost"]', 1, 'The deployed workloads themselves don''t need backing up -- restoring ArgoCD''s own Application/AppProject/config state and letting it re-sync from Git achieves the same result, since that re-sync is the entire point of GitOps.', 'advanced'),
('devops', 'argocd', 'advanced', 'What is the actual difference between a plain ArgoCD-managed Deployment''s rolling update and an Argo Rollouts canary strategy with an AnalysisTemplate?', '["They are the same mechanism with different names", "A plain rolling update replaces pods gradually with no automated health judgment; Argo Rollouts'' canary strategy shifts a controlled percentage of traffic and uses the AnalysisTemplate to automatically query real metrics (e.g. Prometheus success rate) to decide whether to promote or abort", "Rolling updates cannot be paused, while canary strategies always run instantly", "AnalysisTemplate only works with blue-green strategies, never canary"]', 1, 'The real value is automated, metric-driven promotion -- if the success-rate query drops below the configured threshold during a canary step, Rollouts aborts and rolls back on its own, without requiring someone to be watching a dashboard in real time.', 'advanced'),
('devops', 'argocd', 'advanced', 'What does the ApplicationSet Matrix generator produce that combining a Git directory generator and a Cluster generator separately cannot achieve as cleanly?', '["Matrix generators can only be used with the List generator, never Git or Cluster", "The Cartesian product of both child generators -- e.g. every service directory deployed to every matching cluster -- from one ApplicationSet definition that scales automatically as either dimension grows", "It removes the need for an AppProject when deploying to multiple clusters", "Matrix generators are deprecated in favor of separate ApplicationSets per cluster"]', 1, 'Without Matrix, deploying N services to M clusters means either N*M hand-written Applications or M separate Git-directory ApplicationSets (one per cluster) -- Matrix produces all N*M Applications from a single definition, with no ApplicationSet change needed when either N or M grows.', 'advanced'),
('devops', 'argocd', 'advanced', 'In an HA ArgoCD deployment, what does enabling Redis HA (sentinel-backed) actually protect against, given that Git remains the ultimate source of truth regardless?', '["It prevents any data loss whatsoever, since Redis holds the authoritative desired state", "It avoids every ArgoCD component having to re-read from the Kubernetes API and Git under real load if Redis becomes unavailable -- Redis backs caching, not the source of truth", "Redis HA is required before ArgoCD can manage more than one Application", "It replaces the need for backing up Application and AppProject objects"]', 1, 'Losing a single-instance Redis is not data loss -- Git and the live cluster state are still intact -- but it does mean real added load on the Kubernetes API and Git server until every component rebuilds its cache from scratch, which HA Redis avoids.', 'advanced')

ON CONFLICT (academy_slug, technology_slug, section_slug, question) DO NOTHING;
